```javascript
function debounce(callback, delay) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => callback(...args), delay);
  };
}

const search = debounce((term) => console.log("search", term), 250);
search("j");
search("js"); // only this call runs after the pause
```

```javascript
let currentRequest = 0;
let controller;

async function search(term) {
  const requestId = ++currentRequest;
  controller?.abort();
  controller = new AbortController();

  try {
    const response = await fetch(`/api/search?q=${encodeURIComponent(term)}`, { signal: controller.signal });
    const results = await response.json();
    if (requestId === currentRequest) render(results);
  } catch (error) {
    if (error.name !== "AbortError" && requestId === currentRequest) showError(error);
  }
}
function render() {}
function showError() {}
